#include <bits/stdc++.h>
using namespace std;

pair<int, vector<int>> bfs(int start, const vector<vector<int>>& adj) {
    int n = (int)adj.size() - 1;
    vector<int> dist(n + 1, -1), parent(n + 1, 0);
    queue<int> q;

    dist[start] = 0;
    q.push(start);

    int far = start;

    while (!q.empty()) {
        int u = q.front();
        q.pop();

        if (dist[u] > dist[far]) far = u;

        for (int v : adj[u]) {
            if (dist[v] == -1) {
                dist[v] = dist[u] + 1;
                parent[v] = u;
                q.push(v);
            }
        }
    }

    return {far, parent};
}

int getCenter(int n, const vector<vector<int>>& adj) {
    auto [a, parent1] = bfs(1, adj);
    auto [b, parent2] = bfs(a, adj);

    vector<int> path;
    int cur = b;

    while (true) {
        path.push_back(cur);
        if (cur == a) break;
        cur = parent2[cur];
    }

    reverse(path.begin(), path.end());

    int diameterEdges = (int)path.size() - 1;
    return path[diameterEdges / 2];
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;

    vector<vector<int>> adj1(N + 1), adj2(M + 1);

    for (int i = 0; i < N - 1; i++) {
        int A, B;
        cin >> A >> B;
        adj1[A].push_back(B);
        adj1[B].push_back(A);
    }

    for (int i = 0; i < M - 1; i++) {
        int X, Y;
        cin >> X >> Y;
        adj2[X].push_back(Y);
        adj2[Y].push_back(X);
    }

    int c1 = getCenter(N, adj1);
    int c2 = getCenter(M, adj2);

    cout << c1 << ' ' << c2 << '\n';

    return 0;
}
